import{_ as i,l as r,o as e,c as d,v as n,p as l,x as o,d as s,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"自由处置与 Inada","description":"","frontmatter":{"title":"自由处置与 Inada","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/free-disposal-inada.md","filePath":"econ/free-disposal-inada.md","lastUpdated":1789023840000}'),c={name:"econ/free-disposal-inada.md"};function f(A,a,h,_,m,B){const t=r("Mermaid");return e(),d("div",null,[a[1]||(a[1]=n('<h1 id="自由处置与-inada" tabindex="-1">自由处置与 Inada <a class="header-anchor" href="#自由处置与-inada" aria-label="Permalink to &quot;自由处置与 Inada&quot;">​</a></h1><div class="epigraph"><p>浪费仍可行，最优却不会去浪费；Inada 则保证最优不会把某种要素用到零——两刀一起，把分析钉在有效内点上。</p><footer>—— 据 Mas-Colell, Whinston and Green 第 5 章；Inada, On a Two-Sector Model of Economic Growth, Review of Economic Studies, 1963 整理</footer></div><p><a href="/econ/production-technology">上一课</a>给出了生产集 \\(Y\\)、规模报酬与 TRS，并把免费处置列为常用限制之一。本课不重写锥与等产量，也不把替代弹性再定义一遍。缺口是：后课成本最小化要内点投入与可微一阶条件，必须把「免费处置」从清单上的一句话，升级成有效点的几何，并用 Inada 条件挡住角点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(Y\\) 上可以有浪费：多用投入、少产，物质上仍做得到。若分析对象是整块 \\(Y\\)，最优问题的解可能躺在内部的无效点上，一阶条件对不上 TRS。缺口是把自由处置写成：若 \\(y\\in Y\\) 且 \\(y&#39;\\le y\\)（净产出更差），则 \\(y&#39;\\in Y\\)。于是有效边界 \\(\\{y\\in Y:\\text{不存在 }y&#39;\\gt y,\\,y&#39;\\in Y\\}\\) 成为唯一值得选的点——价格为正时，利润或成本不会挑浪费。</p><p>单产出 \\(q=f(z)\\)、\\(z\\ge 0\\) 时，自由处置体现为 \\(f\\) 非降：多投入可以扔掉，产出不会被迫下降。仍不够挡住 \\(z_j=0\\)。Inada 条件在光滑凹的 \\(f\\) 上要求</p> \\[\\lim_{z_j\\to 0^+}\\frac{\\partial f}{\\partial z_j}=+\\infty,\\qquad \\lim_{z_j\\to+\\infty}\\frac{\\partial f}{\\partial z_j}=0, \\]<p>常再加 \\(f(0)=0\\)。边际产出在原点炸掉，要素价格有限时内点最优；在无穷远处熄灭，挡住无限投入。后课 \\(w_j=\\lambda\\,\\mathrm{MP}_j\\) 才有解。</p><h3 id="自由处置不是免费午餐" tabindex="-1">自由处置不是免费午餐 <a class="header-anchor" href="#自由处置不是免费午餐" aria-label="Permalink to &quot;自由处置不是免费午餐&quot;">​</a></h3><p>处置的是已经可行的计划，不是凭空变出正净产出。\\(0\\in Y\\) 是歇业，与「把产出扔掉」不是同一句。IRS 仍然可以与自由处置共存；自由处置不蕴含凸。上一课的锥性质本课不重写。</p><p><span class="marginnote">没有自由处置时，污染、不可弃的副产品会成为联合产出的硬约束。那是外部性课。主干先假定多余的东西可以扔掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把可行计划投影到有效边界：给定投入 \\(z\\)，产出取 \\(f(z)\\) 而不是更小。成本最小化在等产量 \\(\\{f(z)=q\\}\\) 上做，已经默认自由处置把「\\(f(z)\\gt q\\)」的浪费排除出最优。Inada 再保证切点不落在坐标轴上：若 \\(z_j=0\\) 而 \\(\\mathrm{MP}_j=+\\infty\\)，用一点点 \\(j\\) 去替代别的要素，成本无限下降，角点站不住。</p><p>Cobb–Douglas 满足 Inada；线性技术、里昂惕夫不满足——后者角点或折拐是正常的，后课要用超微分，不能假装有内点 TRS。本课标明工作假设落在哪一边。</p>',14)),(e(),l(E,null,{default:o(()=>[p(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E7%94%9F%E4%BA%A7%E9%9B%86%20Y%22%5D%20--%3E%20FD%5B%22%E8%87%AA%E7%94%B1%E5%A4%84%E7%BD%AE%EF%BC%9A%E6%9C%89%E6%95%88%E8%BE%B9%E7%95%8C%22%5D%0A%20%20FD%20--%3E%20ISO%5B%22%E7%AD%89%E4%BA%A7%E9%87%8F%E5%8F%96%E6%9C%80%E5%A4%A7%E4%BA%A7%E5%87%BA%22%5D%0A%20%20ISO%20--%3E%20INADA%5B%22Inada%EF%BC%9AMP%20%E5%9C%A8%200%20%E4%B8%BA%20%E2%88%9E%E3%80%81%E5%9C%A8%20%E2%88%9E%20%E4%B8%BA%200%22%5D%0A%20%20INADA%20--%3E%20INT%5B%22%E5%86%85%E7%82%B9%E6%8A%95%E5%85%A5%22%5D%0A%20%20INT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%BD%90%E6%AC%A1%E4%B8%8E%E6%AC%A7%E6%8B%89%E5%88%86%E9%85%8D%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>本课仍不引入 \\(w\\)、\\(p\\)。Inada 是 \\(f\\) 的形状，不是要素市场。也不把 \\(Y\\) 写成限价簿可成交量。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自由处置让正价格下的浪费严格次优：扔掉产出少收钱，多用投入多付钱。于是包络、Shephard 后课可以对着边界写。Inada 的机制是边际：原点处一点点要素值无穷，有限的 \\(w_j\\) 买得起「第一滴」；无穷远处边际贡献为零，有限的 \\(w_j\\) 买不起无限堆。两刀合在一起，正则情形是 \\(z\\gg 0\\)、\\(q=f(z)\\)、TRS 存在。</p><p>与规模报酬正交：CRS 的 Cobb–Douglas 可以 Inada；DRS 的 \\(f\\) 也可以。Inada 不管锥，只管轴上的导数。</p><p><span class="marginnote">增长理论里 Inada 用来保证正的稳态资本。微观生产课借用同一形状，目的是内点要素需求，不是索洛图。不要把本课写成增长附录。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>整数机器、最小开工规模，Inada 失败，角点是本质。不可自由处置的有害产出，有效边界要改成「少排」也是一种产出坐标。后课若用内点一阶条件，默认已经站在本课这一边。</p><p>\\(f\\) 在零处无定义或不可微，极限改成一侧超微分「足够陡」。本课不展开。也不处理状态依存生产：收成随天气只需给 \\(f\\) 加下标 \\(s\\)，自由处置与 Inada 逐状态陈述即可。</p><p>后课默认：分析在有效边界上进行；需要内点投入时，\\(f\\) 满足 Inada。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自由处置把浪费标成可行但非有效；正价格下最优在边界。</li><li>Inada 让边际产出在原点无穷、在无穷远处为零，从而内点。</li><li>两刀不蕴含凸或 CRS；角点技术（里昂惕夫）不走这条正则。</li><li>下一课在齐次技术上写欧拉分配。</li><li>出处：Mas-Colell, Whinston and Green 第 5 章；Inada, <em>Review of Economic Studies</em>, 1963。</li></ul>',11))])}const S=i(c,[["render",f]]);export{u as __pageData,S as default};
